export class People {
  private readonly session = inject(Session);
  private readonly document = inject(DOCUMENT);
  private readonly api = inject(PeopleApi);
  private readonly claimsApi = inject(ClaimsApi);
  private readonly ratesApi = inject(RatesApi);
  private readonly periodsApi = inject(PeriodsApi);
  private readonly floor = inject(SheetFloor);
  private readonly latePct = inject(SheetLatePct);
  private readonly policyDate = inject(SheetPolicyDate);
  private readonly cap = inject(SheetCap);
  /** What a late charge goes by: the sheet's today and late percent; and the policy date rounding goes by. */
  private readonly late = computed<Lateness>(() => ({
    today: this.session.today(),
    latePct: this.latePct.on(),
    policyDate: this.policyDate.value() ?? this.session.today(),
  }));

  protected readonly grades: Grade[] = ['A', 'B', 'C'];
  protected readonly people = signal<Person[]>([]);
  /** Whether retired people are listed; off when the screen opens, and kept as it is by loading a sheet. */
  protected readonly showRetired = signal(false);
  /** The people listed: everyone, or only those not retired on the sheet's today (one retired from a later date
   * is still listed) unless retired people are shown. Totals count everyone either way. */
  protected readonly shownPeople = computed(() => {
    const today = this.session.today() ?? '';
    return this.showRetired()
      ? this.people()
      : this.people().filter((p) => !p.retiredFrom || p.retiredFrom > today);
  });
  /** The sheet's claims, newest first. */
  protected readonly claims = signal<Claim[]>([]);
  private readonly claimsByPerson = computed(() => {
    const by = new Map<number, Claim[]>();
    for (const c of this.claims()) by.set(c.personId, [...(by.get(c.personId) ?? []), c]);
    return by;
  });
  /** Each person's holds, by id: their OPEN and PENDING claims dated within one, unless bound, count in no total. */
  private readonly holdsById = computed(() => new Map(this.people().map((p) => [p.id, p.holds])));
  /** Each person's retired-from date, by id: from the sheet's today on or after it, their OPEN and PENDING claims,
   * unless bound, count in no total. */
  private readonly retiredById = computed(() => new Map(this.people().map((p) => [p.id, p.retiredFrom])));
  protected readonly claimedTotal = computed(() =>
    sumAmounts(this.claims().filter((c) => this.countsLive(c)).map((c) => c.amount)),
  );
  /** The sheet's rates. */
  protected readonly rates = signal<Rate[]>([]);
  /** The rate each grade with one has in force on the sheet's today. */
  protected readonly rateByGrade = computed(() => {
    const today = this.session.today() ?? '';
    const by = new Map<Grade, string>();
    for (const g of this.grades) {
      const rate = rateOn(this.rates(), g, today);
      if (rate !== undefined) by.set(g, rate);
    }
    return by;
  });

  /** The sheet's periods by from-date. */
  protected readonly periods = signal<Period[]>([]);
  /** Each period's due-total for each person, by period id then person id: the sum of the dues, as shown now,
   * of the person's claims dated in it that count by the status they had at the end of its last day (n/a ones
   * skipped), 0.00 with none; a closed period's are the ones
   * fixed when it closed, 0.00 for a person who had none then. */
  protected readonly personPeriodDueTotals = computed(() => {
    const byId = new Map(this.people().map((p) => [p.id, p]));
    const dues = new Map<number, Map<number, string[]>>();
    for (const c of this.claims()) {
      const period = periodOf(this.periods(), c.date);
      const person = byId.get(c.personId);
      if (!period || period.closed || !person || !this.countsAt(c, period.to)) continue;
      const due = this.claimDue(c, person);
      if (due === NO_RATE) continue;
      const byPerson = dues.get(period.id) ?? new Map<number, string[]>();
      byPerson.set(person.id, [...(byPerson.get(person.id) ?? []), due]);
      dues.set(period.id, byPerson);
    }
    return new Map(
      this.periods().map((pd) => [
        pd.id,
        new Map(
          this.people().map((p) => [
            p.id,
            pd.closed
              ? (pd.personTotals?.[p.id] ?? '0.00')
              : sumAmounts(dues.get(pd.id)?.get(p.id) ?? []),
          ]),
        ),
      ]),
    );
  });
  /** Each period's due-total, by id: the sum of the people's due-totals for it. */
  protected readonly periodDueTotals = computed(
    () => new Map([...this.personPeriodDueTotals()].map(([id, byPerson]) => [id, sumAmounts([...byPerson.values()])])),
  );

  /** The sheet's due-total: the people's due-totals (n/a ones skipped) added up, trimmed of the highest and lowest. */
  protected readonly dueTotal = computed(() =>
    trimmedSum(this.people().map((p) => this.personDueTotal(p)).filter((d) => d !== NO_RATE)),
  );
  /** Per grade, the people not retired who have it on the sheet's today, their due-totals added up (n/a
   * ones skipped), and how many of them are active. */
  protected readonly gradeSummary = computed<GradeSummary[]>(() =>
    this.grades.map((grade) => {
      const on = this.people().filter((p) => !p.retiredFrom && this.gradeToday(p) === grade);
      const dueTotal = sumAmounts(on.map((p) => this.personDueTotal(p)).filter((d) => d !== NO_RATE));
      return { grade, count: on.length, dueTotal, active: on.filter((p) => this.isActive(p)).length };
    }),
  );
  /** How many of the sheet's claims have each status. */
  protected readonly statusCounts = computed(() => {
    const by = new Map<string, number>();
    for (const c of this.claims()) by.set(c.status, (by.get(c.status) ?? 0) + 1);
    return by;
  });
  /** How many of the sheet's claims that count are overdue, and the sum of their dues (n/a ones skipped). */
  protected readonly overdueCount = computed(() =>
    this.people().reduce((n, p) => n + this.overdueOf(p).length, 0),
  );
  /** The sheet's overdue-total: the people's overdue-totals added up, trimmed of the highest and lowest. */
  protected readonly overdueTotal = computed(() => trimmedSum(this.people().map((p) => this.overdueTotalOf(p))));
  /** The ids of the claims selected to open together. */
  protected readonly selectedClaims = signal<ReadonlySet<number>>(new Set());
  /** How many claims the last open of the selected ones opened and refused. */
  protected readonly bulkOpenResult = signal<{ opened: number; refused: number } | null>(null);
  protected readonly bulkOpenError = signal<string | null>(null);
  /** Whether an open of the selected claims is waiting on the server; another is ignored until it answers. */
  private bulkOpening = false;
  /** How many claims the last settle of the selected ones settled (or sent PENDING) and refused. */
  protected readonly bulkSettleResult = signal<{ settled: number; refused: number } | null>(null);
  protected readonly bulkSettleError = signal<string | null>(null);
  /** Whether a settle of the selected claims is waiting on the server; another is ignored until it answers. */
  private bulkSettling = false;
  protected readonly editingId = signal<number | null>(null);
  /** The version of the person the editor loaded. */
  private editingVersion: number | null = null;
  /** Whether a submit is waiting on the server; another submit is ignored until it answers. */
  private submitting = false;
  protected readonly formError = signal<string | null>(null);
  /** The error of the last action taken on a person's row, shown on that row. */
  protected readonly personError = signal<{ id: number; message: string } | null>(null);
  /** Whether the signed-in user watches a person, by id, as their last watch toggle on this load left it; a person
   * not toggled since the sheet was read shows what was read. */
  private readonly watchedNow = signal<ReadonlyMap<number, boolean>>(new Map());
  /** The error of the last patron added on a person's row, shown on that row. */
  protected readonly patronError = signal<{ id: number; message: string } | null>(null);
  protected readonly form = new FormGroup({
    name: new FormControl('', { nonNullable: true }),
    grade: new FormControl<Grade>('A', { nonNullable: true }),
    /** The date a saved grade is in force from; the sheet's today unless another date is picked. */
    gradeFrom: new FormControl('', { nonNullable: true }),
    /** The person's own terms in days; blank for none. */
    terms: new FormControl('', { nonNullable: true }),
  });

  /** Whether a quick-add is waiting on the server; another is ignored until it answers. */
  private quickAdding = false;
  protected readonly quickError = signal<string | null>(null);
  protected readonly quickForm = new FormGroup({
    name: new FormControl('', { nonNullable: true }),
    amount: new FormControl('', { nonNullable: true }),
  });

  /** Whether a paste is waiting on the server; another is ignored until it answers. */
  private pasting = false;
  protected readonly pasteForm = new FormGroup({ text: new FormControl('', { nonNullable: true }) });
  /** How many claims the last paste added. */
  protected readonly pasteAdded = signal<number | null>(null);
  protected readonly pasteError = signal<string | null>(null);

  constructor() {
    this.pasteForm.valueChanges.subscribe(() => this.pasteError.set(null));
    this.form.valueChanges.subscribe(() => this.formError.set(null));
    this.quickForm.valueChanges.subscribe(() => this.quickError.set(null));
    effect(() => {
      const today = this.session.today() ?? '';
      untracked(() => {
        if (!this.form.controls.gradeFrom.dirty) this.form.controls.gradeFrom.setValue(today, { emitEvent: false });
      });
    });
    // Re-read the sheet's people and their claims from the store each time a sheet is loaded.
    const loaded = this.session.registerLoader(inject(DestroyRef));
    toObservable(this.session.sheetLoad)
      .pipe(
        map((l) => l?.id ?? null),
        switchMap((id) =>
          id
            ? forkJoin({
                id: of(id),
                people: this.api.list(id),
                claims: this.claimsApi.list(id),
                rates: this.ratesApi.list(id),
                periods: this.periodsApi.list(id),
              })
            : of({ id, people: [] as Person[], claims: [] as Claim[], rates: [] as Rate[], periods: [] as Period[] }),
        ),
      )
      .subscribe(({ id, people, claims, rates, periods }) => {
        this.people.set(people);
        this.watchedNow.set(new Map());
        this.periods.set(periods);
        this.claims.set(claims);
        this.rates.set(rates);
        this.selectedClaims.set(new Set());
        this.bulkOpenResult.set(null);
        this.bulkOpenError.set(null);
        this.bulkSettleResult.set(null);
        this.bulkSettleError.set(null);
        this.pasteAdded.set(null);
        this.pasteError.set(null);
        this.reset();
        loaded(id);
      });
  }

  protected claimsOf(personId: number): Claim[] {
    return this.claimsByPerson().get(personId) ?? [];
  }

  protected claimed(personId: number): string {
    return sumAmounts(this.claimsOf(personId).filter((c) => this.countsLive(c)).map((c) => c.amount));
  }

  /** The grade the person has in force on the sheet's today. */
  protected gradeToday(person: Person): Grade {
    const today = this.session.today();
    return (today !== null ? gradeOn(person.grades, today) : undefined) ?? person.grade;
  }

  /** What is due on a claim of the person's, at the grade they have on the claim's date. */
  private claimDue(claim: Claim, person: Person): string {
    return claimDue(claim, this.rates(), gradeOn(person.grades, claim.date), this.floor.on(), this.late(),
      roundsBy(claim, this.claimsOf(person.id)));
  }

  /** The sum of the dues of the claims the person has that count (n/a ones skipped), 0.00 with none. A
   * person shows n/a when neither the grade they have on the sheet's today nor one they had on the date of a
   * claim that counts has a rate in force on the sheet's today, unless a claim that counts has a figure
   * (kept by a settlement or statement, or at a rate that applies on its date). Not held to the cap. */
  private uncappedDueTotal(person: Person): string {
    const counted = this.claimsOf(person.id).filter((c) => this.countsLive(c));
    const dues = counted.map((c) => this.claimDue(c, person)).filter((d) => d !== NO_RATE);
    const grades = [this.gradeToday(person), ...counted.map((c) => gradeOn(person.grades, c.date))];
    if (!grades.some((g) => g !== undefined && this.rateByGrade().has(g)) && dues.length === 0) return NO_RATE;
    return sumAmounts(dues);
  }

  /** The person's due-total held to the sheet's cap: the cap when the sum of their dues is above it; n/a is not
   * capped. */
  protected personDueTotal(person: Person): string {
    const total = this.uncappedDueTotal(person);
    const cap = this.cap.value();
    return total !== NO_RATE && cap !== null && hundredths(total) > hundredths(cap) ? cap : total;
  }

  /** What the sum of the person's dues is above the sheet's cap; 0.00 when it is not, or is n/a. */
  protected excess(person: Person): string {
    const total = this.uncappedDueTotal(person);
    if (total === NO_RATE) return '0.00';
    return fromHundredths(hundredths(total) - hundredths(this.personDueTotal(person)));
  }

  /** Whether the person is active: they have an OPEN or PENDING claim that counts dated within the 30 days up
   * to and including the sheet's today. */
  protected isActive(person: Person): boolean {
    const today = this.session.today();
    if (today === null) return false;
    const from = new Date(Date.parse(today) - (ACTIVE_DAYS - 1) * 86_400_000).toISOString().slice(0, 10);
    return this.claimsOf(person.id).some(
      (c) => isOpen(c) && this.countsLive(c) && c.date >= from && c.date <= today,
    );
  }

  /** The person's claims that count and are overdue. */
  protected overdueOf(person: Person): Claim[] {
    const today = this.session.today();
    return this.claimsOf(person.id).filter((c) => this.countsLive(c) && isOverdue(c, today));
  }

  /** The sum of the dues of the person's overdue claims that count (n/a ones skipped), 0.00 with none. */
  protected overdueTotalOf(person: Person): string {
    return sumAmounts(
      this.overdueOf(person)
        .map((c) => this.claimDue(c, person))
        .filter((d) => d !== NO_RATE),
    );
  }

